128	    /**
129	     * A figure with the claim's late charge on top while an OPEN or PENDING claim is past its due-by
130	     * (fixed when it was added) on the sheet's today (see {@link #lateOn}), rounded by the claim's date
131	     * against the policy date. The charge is never bound: it always follows the sheet's today.
132	     * A correction has no late charge, nor has a claim deferred on the sheet's today (it is not overdue).
133	     */
134	    private BigDecimal withLate(Claim claim, BigDecimal figure, Basis basis) {
135	        if (figure == null || claim.isCorrection() || !claim.getStatus().isOpen() || claim.getSettledDue() != null) {
136	            return figure;
137	        }
138	        if (basis.sheet() != null && claim.isDeferredOn(basis.today())) {
139	            return figure;
140	        }
141	        return lateOn(claim, figure, basis);
142	    }
143	
144	    /**
145	     * A figure with the late charge an OPEN claim would have on the sheet's today on top: for every full
146	     * 30 days past its due-by, the late percent in force on that boundary date (the due-by plus 30, 60,
147	     * 90 ... days) of the figure, rounded like the claim, the charges added up.
148	     */
149	    private BigDecimal lateOn(Claim claim, BigDecimal figure, Basis basis) {
150	        Sheet sheet = basis.sheet();
151	        if (sheet == null) {
152	            return figure;
153	        }
154	        LocalDate dueBy = claim.getDueBy();
155	        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / 30;
156	        RoundingMode rounding = rounding(claim, basis);
157	        BigDecimal late = BigDecimal.ZERO.setScale(2);
158	        for (long period = 1; period <= periods; period++) {
159	            BigDecimal latePct = sheet.latePctOn(dueBy.plusDays(30 * period));
160	            if (latePct != null && latePct.signum() != 0) {
161	                late = late.add(figure.multiply(latePct).movePointLeft(2).setScale(2, rounding));
162	            }
163	        }
164	        return figure.add(late);
165	    }
