167	    /**
168	     * A due raised to the floor in force on the claim's date when below it, applied last (after the
169	     * late charge); a correction has no floor, and null (n/a) stays null.
170	     */
171	    private BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
172	        if (due == null || claim.isCorrection()) {
173	            return due;
174	        }
175	        Sheet sheet = basis.sheet();
176	        BigDecimal floor = sheet == null ? null : sheet.floorOn(claim.getDate());
177	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
178	    }
179	
180	    /**
181	     * A claim's rate figure: its amount at the rate the grade has in force on the claim's date, rounded
182	     * by the claim's date against the policy date, with no floor; null when it has no rate.
183	     */
184	    public BigDecimal live(Claim claim, String grade) {
185	        return live(claim, grade, live(claim.getSheetId()));
186	    }
187	
188	    private BigDecimal live(Claim claim, String grade, Basis basis) {
189	        RoundingMode rounding = rounding(claim, basis);
190	        return basis.rateInForce(grade, claim.getDate())
191	                .map(rate -> due(claim.getAmount(), rate, rounding))
192	                .orElse(null);
193	    }
194	
195	    /** What is due on an amount at a rate: the amount times the percent over 100, rounded as given. */
196	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
197	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
198	    }
