export function statusAt(claim: ClaimView, day: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let then: ClaimStatus | null = null;
  for (const line of claim.log) {
    if (line.on <= day) then = line.status;
  }
  return then;
}

