13	import org.springframework.transaction.annotation.Transactional;
14	
15	/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
16	@Service
17	public class SheetService {
18	
19	    private final SheetRepository sheets;
20	    private final Rollups rollups;
21	    private final Audit audit;
22	    private final ApplicationEventPublisher events;
23	
24	    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit, ApplicationEventPublisher events) {
25	        this.sheets = sheets;
26	        this.rollups = rollups;
27	        this.audit = audit;
28	        this.events = events;
29	    }
30	
31	    /** Load a sheet; a new sheet's today starts as the real date. */
32	    @Transactional
33	    public synchronized Sheet load(String id) {
34	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
35	    }
36	
37	    /**
38	     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
39	     * this, never the real clock.
40	     */
41	    @Transactional(readOnly = true)
42	    public LocalDate today(String id) {
43	        return load(id).getToday();
44	    }
45	
46	    /**
47	     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
48	     * the sheet's other rows before writing are made one at a time.
49	     */
50	    @Transactional
51	    public Sheet lock(String id) {
52	        load(id);
53	        return sheets.findLockedById(id).orElseThrow();
54	    }
55	
56	    /**
57	     * Change the sheet's today, auditing the figures that moves. When it moves, each person's due-total
58	     * as it stood on the day being left is audited first, in list order, and the sheet as it stood at
59	     * the end of that day is kept (see {@link TodayLeaving}). The periods it puts past their grace
60	     * days are closed (see {@link TodayChanged}) before those figures are audited.
61	     */
62	    @Transactional
63	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
64	        Sheet sheet = load(id);
65	        Rollups.Rollup before = rollups.take(id);
66	        if (!today.equals(sheet.getToday())) {
67	            before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
68	                    + " name=" + figures.name() + " due-total=" + Rollups.shown(figures.dueTotal())));
69	            events.publishEvent(new TodayLeaving(id, sheet.getToday()));
70	        }
71	        sheet.setToday(today);
72	        Sheet saved = sheets.saveAndFlush(sheet);
73	        events.publishEvent(new TodayChanged(id, user, today, saved.getGraceDays()));
74	        rollups.audit(id, user, before);
75	        return saved;
76	    }
77	
78	    /** Whether the sheet is archived: nothing on it may change. */
79	    @Transactional(readOnly = true)
80	    public boolean archived(String id) {
81	        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
82	    }
83	
84	    /** Archive the sheet; refused when it already is. */
85	    @Transactional
86	    public Sheet archive(String id, String user) {
87	        Sheet sheet = lock(id);
88	        if (sheet.isArchived()) {
89	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is already archived.");
90	        }
91	        sheet.setArchived(true);
92	        Sheet saved = sheets.saveAndFlush(sheet);
93	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
94	        return saved;
95	    }
96	
97	    /** The sheet's clerk limit; null when there is none. */
98	    @Transactional(readOnly = true)
99	    public BigDecimal clerkLimit(String id) {
100	        return load(id).getClerkLimit();
101	    }
102	
103	    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
104	    @Transactional
105	    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
106	        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
107	    }
108	
109	    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
110	    @Transactional
111	    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
112	        return setDated(id, user, Sheet.CAP, money(cap), from, true);
113	    }
114	
115	    /** Record the sheet's proof threshold (null: none) from a date, auditing the change. */
116	    @Transactional
117	    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
118	        return setDated(id, user, Sheet.PROOF_THRESHOLD, money(threshold), from, false);
119	    }
120	
121	    /** Record the sheet's note threshold (null: none) from a date, auditing the change. */
122	    @Transactional
123	    public Sheet setNoteThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
124	        return setDated(id, user, Sheet.NOTE_THRESHOLD, money(threshold), from, false);
125	    }
126	
127	    /** Record the sheet's floor from a date, auditing the change and the figures it moves. */
128	    @Transactional
129	    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
130	        return setDated(id, user, Sheet.FLOOR, money(floor), from, true);
131	    }
132	
133	    /** Record the sheet's terms, in days, from a date, auditing the change; claims keep their due-by. */
134	    @Transactional
135	    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
136	        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, true);
137	    }
138	
139	    /**
140	     * Record a grade's own terms, in days (null: the sheet's terms), from a date, auditing the change.
141	     * Claims keep their due-by.
142	     */
143	    @Transactional
144	    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
145	        return setDated(id, user, Sheet.gradeTermsKey(grade), terms == null ? null : terms.toString(), from, true);
146	    }
147	
148	    /** Record the sheet's late percent from a date, auditing the change and the figures it moves. */
149	    @Transactional
150	    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
151	        return setDated(id, user, Sheet.LATE_PCT, money(latePct), from, true);
152	    }
153	
154	    /**
155	     * Record a dated setting's value (null: none) from a date, the sheet's today when none is given,
156	     * replacing any value recorded from that date. The change is audited, with the from-date when one
157	     * was given, and so are the figures it moves when it can move any.
158	     */
159	    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
160	        Sheet sheet = lock(id);
161	        Rollups.Rollup before = movesFigures ? rollups.take(id) : null;
162	        sheet.record(key, from == null ? sheet.getToday() : from, value);
163	        Sheet saved = sheets.saveAndFlush(sheet);
164	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
165	                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
166	        if (movesFigures) {
167	            rollups.audit(id, user, before);
168	        }
169	        return saved;
170	    }
171	
172	    /** A figure with two decimals as text; null stays null. */
173	    private static String money(BigDecimal value) {
174	        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
175	    }
176	
177	    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
178	    @Transactional
179	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
180	        Sheet sheet = lock(id);
181	        Rollups.Rollup before = rollups.take(id);
182	        sheet.setPolicyDate(policyDate);
183	        Sheet saved = sheets.saveAndFlush(sheet);
184	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
185	                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
186	        rollups.audit(id, user, before);
187	        return saved;
188	    }
189	
190	    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
191	    @Transactional
192	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
193	        Sheet sheet = lock(id);
194	        sheet.setPeriodNumberingFrom(from);
195	        Sheet saved = sheets.saveAndFlush(sheet);
196	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
197	                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
198	        return saved;
199	    }
200	
201	    /** Change the sheet's entry date (null: off), auditing the change. */
202	    @Transactional
203	    public Sheet setEntryDate(String id, String user, LocalDate entryDate) {
204	        Sheet sheet = lock(id);
205	        sheet.setEntryDate(entryDate);
206	        Sheet saved = sheets.saveAndFlush(sheet);
207	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=entry-date value="
208	                + (saved.getEntryDate() == null ? "" : saved.getEntryDate().toString()));
209	        return saved;
210	    }
211	
212	    /** Change the sheet's grace days (null: off), auditing the change. */
213	    @Transactional
214	    public Sheet setGraceDays(String id, String user, Integer graceDays) {
215	        Sheet sheet = lock(id);
216	        sheet.setGraceDays(graceDays);
217	        Sheet saved = sheets.saveAndFlush(sheet);
218	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=grace-days value="
219	                + (saved.getGraceDays() == null ? "" : saved.getGraceDays().toString()));
220	        return saved;
221	    }
222	
223	    /** Set the roles that may take an action (null: the standing rule), auditing the change. */
224	    @Transactional
225	    public Sheet setPermission(String id, String user, String action, String roles) {
226	        Sheet sheet = lock(id);
227	        sheet.setPermission(action, roles);
228	        Sheet saved = sheets.saveAndFlush(sheet);
229	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value="
230	                + (roles == null ? "" : roles));
231	        return saved;
232	    }
233	}
