                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
        return saved;
    }

    /** Change the sheet's entry date (null: off), auditing the change. */
    @Transactional
    public Sheet setEntryDate(String id, String user, LocalDate entryDate) {
        Sheet sheet = lock(id);
